#!/usr/bin/env python3
# Generated by runa via A2A Mesh delegation
"""
Store-and-forward mechanism for A2A Mesh.
Offline node messages are queued and redelivered when the node comes back online.
Includes priority tags (P0-P2) and a decision log for closed votes.
"""

import json
import os
import time
import uuid
import threading
import hashlib
from dataclasses import dataclass, field, asdict
from enum import IntEnum
from typing import Dict, List, Optional, Set, Callable, Any
from collections import defaultdict, deque
from pathlib import Path


class Priority(IntEnum):
    P0 = 0  # urgent / voting
    P1 = 1  # normal
    P2 = 2  # low / chat


class MessageStatus:
    QUEUED = "queued"
    DELIVERED = "delivered"
    EXPIRED = "expired"
    FAILED = "failed"


@dataclass
class MeshMessage:
    """A message in the mesh network."""
    id: str
    sender: str
    recipient: str
    content: str
    priority: Priority = Priority.P1
    timestamp: float = field(default_factory=time.time)
    ttl: float = 86400.0  # 24h default
    status: str = MessageStatus.QUEUED
    delivery_attempts: int = 0
    max_attempts: int = 10
    last_attempt: float = 0.0
    topic: Optional[str] = None
    msg_type: str = "chat"  # chat, vote, decision, capability
    metadata: Dict[str, Any] = field(default_factory=dict)

    def is_expired(self) -> bool:
        return (time.time() - self.timestamp) > self.ttl

    def should_retry(self) -> bool:
        if self.is_expired():
            return False
        if self.delivery_attempts >= self.max_attempts:
            return False
        # exponential backoff: 2^attempts seconds, capped at 300
        backoff = min(2 ** self.delivery_attempts, 300)
        return (time.time() - self.last_attempt) >= backoff

    def to_dict(self) -> dict:
        d = asdict(self)
        d["priority"] = int(self.priority)
        return d

    @classmethod
    def from_dict(cls, d: dict) -> "MeshMessage":
        d = dict(d)
        d["priority"] = Priority(d.get("priority", 1))
        return cls(**d)


@dataclass
class DecisionRecord:
    """A closed vote / decision entry in the decision log."""
    id: str
    topic: str
    question: str
    outcome: str  # accepted, rejected, deferred
    votes_for: int = 0
    votes_against: int = 0
    votes_abstain: int = 0
    participants: List[str] = field(default_factory=list)
    timestamp: float = field(default_factory=time.time)
    closed_at: float = 0.0
    summary: str = ""


class NodeRegistry:
    """Tracks online/offline status of mesh nodes."""

    def __init__(self):
        self._nodes: Dict[str, dict] = {}
        self._lock = threading.RLock()

    def register(self, node_id: str, capabilities: Optional[List[str]] = None):
        with self._lock:
            self._nodes[node_id] = {
                "online": True,
                "last_seen": time.time(),
                "capabilities": capabilities or [],
            }

    def heartbeat(self, node_id: str):
        with self._lock:
            if node_id in self._nodes:
                self._nodes[node_id]["last_seen"] = time.time()
                self._nodes[node_id]["online"] = True

    def set_offline(self, node_id: str):
        with self._lock:
            if node_id in self._nodes:
                self._nodes[node_id]["online"] = False

    def is_online(self, node_id: str) -> bool:
        with self._lock:
            node = self._nodes.get(node_id)
            if not node:
                return False
            # auto-detect offline after 60s without heartbeat
            if time.time() - node["last_seen"] > 60:
                node["online"] = False
            return node["online"]

    def get_online_nodes(self) -> List[str]:
        with self._lock:
            return [nid for nid in self._nodes if self.is_online(nid)]

    def get_all_nodes(self) -> Dict[str, dict]:
        with self._lock:
            return dict(self._nodes)


class StoreAndForwardQueue:
    """Persistent queue for messages to offline nodes."""

    def __init__(self, storage_path: str = "mesh_store.json"):
        self.storage_path = Path(storage_path)
        self._queue: Dict[str, List[MeshMessage]] = defaultdict(list)
        self._lock = threading.RLock()
        self._load()

    def _load(self):
        if self.storage_path.exists():
            try:
                data = json.loads(self.storage_path.read_text(encoding="utf-8"))
                for node_id, msgs in data.items():
                    self._queue[node_id] = [
                        MeshMessage.from_dict(m) for m in msgs
                    ]
            except (json.JSONDecodeError, KeyError, TypeError):
                pass

    def _save(self):
        with self._lock:
            data = {}
            for node_id, msgs in self._queue.items():
                data[node_id] = [m.to_dict() for m in msgs]
            self.storage_path.write_text(
                json.dumps(data, indent=2, ensure_ascii=False),
                encoding="utf-8"
            )

    def enqueue(self, msg: MeshMessage):
        with self._lock:
            self._queue[msg.recipient].append(msg)
            self._save()

    def get_pending(self, node_id: str) -> List[MeshMessage]:
        with self._lock:
            return list(self._queue.get(node_id, []))

    def mark_delivered(self, node_id: str, msg_id: str):
        with self._lock:
            self._queue[node_id] = [
                m for m in self._queue.get(node_id, [])
                if m.id != msg_id
            ]
            self._save()

    def purge_expired(self) -> int:
        with self._lock:
            purged = 0
            for node_id in list(self._queue.keys()):
                before = len(self._queue[node_id])
                self._queue[node_id] = [
                    m for m in self._queue[node_id]
                    if not m.is_expired()
                ]
                purged += before - len(self._queue[node_id])
            self._save()
            return purged

    def get_stats(self) -> dict:
        with self._lock:
            stats = {
                "total_pending": 0,
                "by_priority": {0: 0, 1: 0, 2: 0},
                "by_node": {},
            }
            for node_id, msgs in self._queue.items():
                stats["by_node"][node_id] = len(msgs)
                stats["total_pending"] += len(msgs)
                for m in msgs:
                    stats["by_priority"][int(m.priority)] += 1
            return stats


class DecisionLog:
    """Auto-trims closed votes into a compact decision record."""

    def __init__(self, storage_path: str = "mesh_decisions.json"):
        self.storage_path = Path(storage_path)
        self._records: List[DecisionRecord] = []
        self._lock = threading.RLock()
        self._load()

    def _load(self):
        if self.storage_path.exists():
            try:
                data = json.loads(self.storage_path.read_text(encoding="utf-8"))
                self._records = [DecisionRecord(**r) for r in data]
            except (json.JSONDecodeError, TypeError):
                pass

    def _save(self):
        with self._lock:
            data = [asdict(r) for r in self._records]
            self.storage_path.write_text(
                json.dumps(data, indent=2, ensure_ascii=False),
                encoding="utf-8"
            )

    def add(self, record: DecisionRecord):
        with self._lock:
            record.closed_at = time.time()
            self._records.append(record)
            self._save()

    def get_all(self) -> List[DecisionRecord]:
        with self._lock:
            return list(self._records)

    def get_by_topic(self, topic: str) -> List[DecisionRecord]:
        with self._lock:
            return [r for r in self._records if r.topic == topic]

    def trim(self, max_records: int = 100) -> int:
        with self._lock:
            if len(self._records) <= max_records:
                return 0
            removed = len(self._records) - max_records
            self._records = self._records[-max_records:]
            self._save()
            return removed


class StoreAndForwardMesh:
    """
    Main mesh agent with store-and-forward capability.
    Nodes can go offline; their messages are queued and redelivered on reconnect.
    """

    def __init__(self, node_id: str, storage_dir: str = "."):
        self.node_id = node_id
        self.storage_dir = Path(storage_dir)
        self.storage_dir.mkdir(parents=True, exist_ok=True)

        self.registry = NodeRegistry()
        self.queue = StoreAndForwardQueue(
            str(self.storage_dir / "mesh_store.json")
        )
        self.decisions = DecisionLog(
            str(self.storage_dir / "mesh_decisions.json")
        )

        self._inbox: deque = deque()
        self._inbox_lock = threading.RLock()
        self._running = False
        self._delivery_callback: Optional[Callable[[MeshMessage], bool]] = None
        self._message_handlers: Dict[str, Callable] = {}

        # Register self
        self.registry.register(node_id, capabilities=["store-forward"])

    def set_delivery_callback(self, cb: Callable[[MeshMessage], bool]):
        """Set a callback that attempts to deliver a message.
        Returns True if delivered successfully, False otherwise."""
        self._delivery_callback = cb

    def register_handler(self, msg_type: str, handler: Callable[[MeshMessage], None]):
        self._message_handlers[msg_type] = handler

    def send(
        self,
        recipient: str,
        content: str,
        priority: Priority = Priority.P1,
        msg_type: str = "chat",
        topic: Optional[str] = None,
        ttl: float = 86400.0,
        metadata: Optional[dict] = None,
    ) -> MeshMessage:
        """Send a message to a recipient. If recipient is offline, queue it."""
        msg = MeshMessage(
            id=uuid.uuid4().hex[:16],
            sender=self.node_id,
            recipient=recipient,
            content=content,
            priority=priority,
            msg_type=msg_type,
            topic=topic,
            ttl=ttl,
            metadata=metadata or {},
        )

        # Register recipient if unknown
        if recipient not in self.registry.get_all_nodes():
            self.registry.register(recipient)

        if self.registry.is_online(recipient):
            delivered = self._try_deliver(msg)
            if not delivered:
                self.queue.enqueue(msg)
                print(f"[{self.node_id}] Queued message {msg.id} for {recipient} (delivery failed)")
        else:
            self.queue.enqueue(msg)
            print(f"[{self.node_id}] Queued message {msg.id} for offline node {recipient} (P{int(priority)})")

        return msg

    def _try_deliver(self, msg: MeshMessage) -> bool:
        """Attempt to deliver a single message."""
        msg.delivery_attempts += 1
        msg.last_attempt = time.time()

        if self._delivery_callback:
            try:
                success = self._delivery_callback(msg)
            except Exception as e:
                print(f"[{self.node_id}] Delivery error: {e}")
                success = False
        else:
            # Default: simulate delivery (always succeeds for online nodes)
            success = True

        if success:
            msg.status = MessageStatus.DELIVERED
            self._handle_incoming(msg)
            return True

        msg.status = MessageStatus.QUEUED
        return False

    def _handle_incoming(self, msg: MeshMessage):
        """Process a delivered message through registered handlers."""
        with self._inbox_lock:
            self._inbox.append(msg)

        handler = self._message_handlers.get(msg.msg_type)
        if handler:
            try:
                handler(msg)
            except Exception as e:
                print(f"[{self.node_id}] Handler error for {msg.msg_type}: {e}")

    def receive(self) -> Optional[MeshMessage]:
        """Pop a message from the local inbox."""
        with self._inbox_lock:
            if self._inbox:
                return self._inbox.popleft()
            return None

    def node_online(self, node_id: str):
        """Mark a node as back online and trigger redelivery."""
        self.registry.heartbeat(node_id)
        print(f"[{self.node_id}] Node {node_id} came online — flushing queue")
        self._flush_queue(node_id)

    def node_offline(self, node_id: str):
        self.registry.set_offline(node_id)
        print(f"[{self.node_id}] Node {node_id} went offline")

    def _flush_queue(self, node_id: str):
        """Deliver all pending messages for a node, sorted by priority."""
        pending = self.queue.get_pending(node_id)
        # Sort by priority (P0 first), then timestamp
        pending.sort(key=lambda m: (int(m.priority), m.timestamp))

        delivered = 0
        for msg in pending:
            if msg.is_expired():
                msg.status = MessageStatus.EXPIRED
                self.queue.mark_delivered(node_id, msg.id)
                print(f"[{self.node_id}] Expired message {msg.id} purged")
                continue

            if self._try_deliver(msg):
                self.queue.mark_delivered(node_id, msg.id)
                delivered += 1
                print(f"[{self.node_id}] Redelivered {msg.id} to {node_id} (P{int(msg.priority)})")
            else:
                break  # stop if delivery fails

        if delivered:
            print(f"[{self.node_id}] Flushed {delivered} messages to {node_id}")

    def start(self):
        """Start background maintenance thread."""
        self._running = True
        t = threading.Thread(target=self._maintenance_loop, daemon=True)
        t.start()
        print(f"[{self.node_id}] Store-and-forward agent started")

    def stop(self):
        self._running = False

    def _maintenance_loop(self):
        while self._running:
            time.sleep(5)
            # Purge expired messages
            purged = self.queue.purge_expired()
            if purged:
                print(f"[{self.node_id}] Purged {purged} expired messages")

            # Check if any offline nodes came back (heartbeat-based)
            for node_id in self.registry.get_all_nodes():
                if self.registry.is_online(node_id):
                    pending = self.queue.get_pending(node_id)
                    if pending:
                        self._flush_queue(node_id)

            # Trim decision log
            self.decisions.trim(max_records=200)

    def cast_vote(
        self,
        recipient: str,
        topic: str,
        question: str,
        vote: str,  # "for", "against", "abstain"
    ) -> MeshMessage:
        """Send a vote message with P0 priority."""
        return self.send(
            recipient=recipient,
            content=json.dumps({"vote": vote, "question": question}),
            priority=Priority.P0,
            msg_type="vote",
            topic=topic,
            ttl=3600.0,  # votes expire in 1h
        )

    def close_vote(
        self,
        topic: str,
        question: str,
        votes_for: int,
        votes_against: int,
        votes_abstain: int,
        participants: List[str],
    ) -> DecisionRecord:
        """Close a vote and log the decision."""
        if votes_for > votes_against:
            outcome = "accepted"
        elif votes_against > votes_for:
            outcome = "rejected"
        else:
            outcome = "deferred"

        summary = f"Vote on '{question}': {votes_for} for, {votes_against} against, {votes_abstain} abstain → {outcome}"

        record = DecisionRecord(
            id=uuid.uuid4().hex[:16],
            topic=topic,
            question=question,
            outcome=outcome,
            votes_for=votes_for,
            votes_against=votes_against,
            votes_abstain=votes_abstain,
            participants=participants,
            summary=summary,
        )
        self.decisions.add(record)
        print(f"[{self.node_id}] Decision logged: {summary}")

        # Broadcast decision to all known nodes at P1
        for node_id in self.registry.get_all_nodes():
            if node_id != self.node_id:
                self.send(
                    recipient=node_id,
                    content=summary,
                    priority=Priority.P1,
                    msg_type="decision",
                    topic=topic,
                )

        return record

    def get_queue_stats(self) -> dict:
        return self.queue.get_stats()

    def get_decision_log(self) -> List[dict]:
        return [asdict(r) for r in self.decisions.get_all()]


