def demo():
    """Demonstrate store-and-forward with offline nodes, priorities, and decisions."""
    print("=" * 70)
    print("A2A Mesh — Store-and-Forward Demo")
    print("=" * 70)

    # Create a temp directory for storage
    demo_dir = Path("./_mesh_demo_data")
    demo_dir.mkdir(exist_ok=True)

    # Create two agents
    alice = StoreAndForwardMesh("alice", storage_dir=str(demo_dir))
    bob = StoreAndForwardMesh("bob", storage_dir=str(demo_dir))

    # Register each other
    alice.registry.register("bob", capabilities=["chat", "vote"])
    bob.registry.register("alice", capabilities=["chat", "vote"])

    # Set delivery callbacks (simulate network)
    def alice_deliver(msg):
        print(f"  [alice→{msg.recipient}] Delivering: {msg.content[:50]}...")
        bob._handle_incoming(msg)
        return True

    def bob_deliver(msg):
        print(f"  [bob→{msg.recipient}] Delivering: {msg.content[:50]}...")
        alice._handle_incoming(msg)
        return True

    alice.set_delivery_callback(alice_deliver)
    bob.set_delivery_callback(bob_deliver)

    # --- Scenario 1: Bob is online, normal message ---
    print("\n--- Scenario 1: Online delivery ---")
    alice.send("bob", "Hello Bob! Are you there?", priority=Priority.P2)

    # --- Scenario 2: Bob goes offline, messages queue up ---
    print("\n--- Scenario 2: Offline queueing ---")
    alice.node_offline("bob")

    alice.send("bob", "Urgent: please review PR #42", priority=Priority.P0, msg_type="vote", topic="pr-42")
    alice.send("bob", "Did you see the new proposal?", priority=Priority.P2)
    alice.send("bob", "Reminder: standup at 10am", priority=Priority.P1)

    stats = alice.get_queue_stats()
    print(f"\nQueue stats: {json.dumps(stats, indent=2)}")

    # --- Scenario 3: Bob comes back online — redelivery ---
    print("\n--- Scenario 3: Redelivery on reconnect ---")
    alice.node_online("bob")

    # Check Bob's inbox
    print("\nBob's inbox:")
    while True:
        msg = bob.receive()
        if msg is None:
            break
        print(f"  [{msg.msg_type}/P{int(msg.priority)}] from {msg.sender}: {msg.content[:60]}")

    # --- Scenario 4: Vote and decision log ---
    print("\n--- Scenario 4: Vote & decision log ---")
    alice.node_offline("bob")
    alice.cast_vote("bob", "topic-merge", "Should we merge feature-branch?", "for")
    alice.cast_vote("bob", "topic-merge", "Should we merge feature-branch?", "against")

    # Bob comes back, receives votes
    alice.node_online("bob")
    print("\nBob's inbox after vote redelivery:")
    votes_for = 0
    votes_against = 0
    while True:
        msg = bob.receive()
        if msg is None:
            break
        print(f"  [{msg.msg_type}/P{int(msg.priority)}] {msg.content[:60]}")
        if msg.msg_type == "vote":
            data = json.loads(msg.content)
            if data["vote"] == "for":
                votes_for += 1
            elif data["vote"] == "against":
                votes_against += 1

    # Close the vote
    record = alice.close_vote(
        topic="topic-merge",
        question="Should we merge feature-branch?",
        votes_for=votes_for,
        votes_against=votes_against,
        votes_abstain=0,
        participants=["alice", "bob"],
    )

    print(f"\nDecision log:")
    for d in alice.get_decision_log():
        print(f"  [{d['outcome']}] {d['summary']}")

    # --- Scenario 5: Priority ordering demonstration ---
    print("\n--- Scenario 5: Priority ordering ---")
    alice.node_offline("bob")
    # Send in reverse priority order
    alice.send("bob", "P2: casual chat message", priority=Priority.P2)
    alice.send("bob", "P1: normal work message", priority=Priority.P1)
    alice.send("bob", "P0: URGENT outage alert", priority=Priority.P0)

    print("Messages queued (should deliver P0 first):")
    alice.node_online("bob")
    while True:
        msg = bob.receive()
        if msg is None:
            break
        print(f"  P{int(msg.priority)}: {msg.content}")

    # --- Final stats ---
    print("\n--- Final queue stats ---")
    print(json.dumps(alice.get_queue_stats(), indent=2))

    print("\n--- Decision log ---")
    print(json.dumps(alice.get_decision_log(), indent=2))

    # Cleanup
    print("\n--- Cleanup ---")
    alice.stop()
    bob.stop()
    import shutil
    shutil.rmtree(demo_dir, ignore_errors=True)
    print("Demo data cleaned up.")
    print("\n✓ Store-and-forward demo complete.")


if __name__ == "__main__":
    demo()